CREATE TABLE carts (id UUID PRIMARY KEY, tenant_id UUID NOT NULL, customer_id UUID NOT NULL, store_id UUID NOT NULL, status VARCHAR(32) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE cart_items (id UUID PRIMARY KEY, cart_id UUID NOT NULL REFERENCES carts(id), tenant_id UUID NOT NULL, sellable_product_id UUID NOT NULL, quantity INTEGER NOT NULL CHECK (quantity > 0), unit_price NUMERIC(19,4) NOT NULL, currency VARCHAR(3) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_carts_tenant_id ON carts(tenant_id); CREATE INDEX idx_carts_customer_id ON carts(customer_id); CREATE INDEX idx_cart_items_cart_id ON cart_items(cart_id); CREATE INDEX idx_cart_items_product_id ON cart_items(sellable_product_id); CREATE INDEX idx_cart_items_tenant_id ON cart_items(tenant_id);
